"""Database access for the monitoring readout."""
import json
import sqlite3

WINDOW_WEEKS = 12
MODEL = "noshow-v3.1"
CANDIDATE = "noshow-v4.0"


def connect(db_path):
    con = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
    con.row_factory = sqlite3.Row
    return con


def last_week(con):
    return con.execute("SELECT MAX(week) AS w FROM appointments").fetchone()["w"]


def window(con):
    lw = last_week(con)
    return (lw - WINDOW_WEEKS + 1, lw)


def appointments(con):
    """Every appointment with what the scorer was served, the scores, the clinic and any reminder call.

    `prior_no_show_count` on `appointments` is the current feature table (see policy_config); the value the
    scorer was given at booking is `feature_snapshots.prior_no_shows_12m`."""
    return con.execute(
        "SELECT a.*, f.prior_no_shows_12m AS served_prior, f.lead_time_days AS served_lead, "
        "       f.deprivation_decile AS served_decile, f.distance_km AS served_distance, "
        "       f.age_band AS served_age, f.appointment_type AS served_type, "
        "       s.score AS score_v31, v.score AS score_v4, c.size_band, rc.outcome AS call_outcome "
        "FROM appointments a "
        "JOIN feature_snapshots f ON f.appt_id = a.appt_id "
        "JOIN clinics c ON c.clinic_id = a.clinic_id "
        "LEFT JOIN model_scores s ON s.appt_id = a.appt_id AND s.model_version = ? "
        "LEFT JOIN model_scores v ON v.appt_id = a.appt_id AND v.model_version = ? "
        "LEFT JOIN reminder_calls rc ON rc.appt_id = a.appt_id "
        "ORDER BY a.appt_id", (MODEL, CANDIDATE)).fetchall()


def did_not_attend_dates(con):
    """Append-only DNA history per patient (including events that predate the extract), sorted."""
    out = {}
    for r in con.execute("SELECT patient_id, event_on FROM attendance_events "
                         "WHERE event_type = 'DID_NOT_ATTEND' ORDER BY patient_id, event_on"):
        out.setdefault(r["patient_id"], []).append(r["event_on"])
    return out


def clinics_with_calls(con):
    return {r["clinic_id"] for r in con.execute(
        "SELECT DISTINCT a.clinic_id FROM reminder_calls rc JOIN appointments a ON a.appt_id = rc.appt_id")}


def registry(con, version=MODEL):
    return con.execute("SELECT * FROM model_registry WHERE model_version = ?", (version,)).fetchone()


def coefficients(con, version=MODEL):
    row = registry(con, version)
    return json.loads(row["coefficients_json"]) if row and row["coefficients_json"] else None


def policy(con):
    return {r["key"]: r["value"] for r in con.execute("SELECT key, value FROM policy_config")}


def monitored_auc(con, lo, hi):
    """Mean of the weekly AUC the monitoring series reports over the window."""
    rows = con.execute(
        "SELECT value FROM monitoring_metrics WHERE metric='auc' AND week BETWEEN ? AND ? ORDER BY week",
        (lo, hi)).fetchall()
    return sum(r["value"] for r in rows) / len(rows) if rows else None
EOF
cat > mlops/scoring.py <<'EOF'
"""Rescoring noshow-v3.1 from the coefficients published in the model registry.

The registry records the feature definitions the model was fitted on: `prior_no_shows_12m` is the count of
did-not-attend events in a rolling window before booking (`feature_window_days`, 365), capped, and the
continuous features are centred.
"""
import bisect
import math
from datetime import date, timedelta

PRIOR_CAP = 3
CENTRES = {"lead_time_days": 21.0, "deprivation_decile": 5.5, "distance_km": 8.0}


def score(coef, prior_no_shows, lead_time_days, deprivation_decile, distance_km, age_band, appointment_type):
    z = (coef["intercept"]
         + coef["prior_no_shows_12m"] * min(prior_no_shows, PRIOR_CAP)
         + coef["lead_time_days_c"] * (lead_time_days - CENTRES["lead_time_days"])
         + coef["deprivation_decile_c"] * (deprivation_decile - CENTRES["deprivation_decile"])
         + coef["distance_km_c"] * (distance_km - CENTRES["distance_km"])
         + coef[f"age_{age_band}"]
         + coef[f"type_{appointment_type}"])
    if z < -35:
        return 0.0
    if z > 35:
        return 1.0
    return 1.0 / (1.0 + math.exp(-z))


def prior_no_shows_asof(dna_dates, booked_on, window_days):
    """DNA events in [booked_on - window_days, booked_on) from the sorted event history."""
    lo = (date.fromisoformat(booked_on) - timedelta(days=window_days)).isoformat()
    return bisect.bisect_left(dna_dates, booked_on) - bisect.bisect_left(dna_dates, lo)


def score_served_features(coef, row):
    """The published model over exactly the values the scorer was given at booking."""
    return score(coef, row["served_prior"], row["served_lead"], row["served_decile"],
                 row["served_distance"], row["served_age"], row["served_type"])


def score_record_asof_window(coef, row, prior_asof):
    """The published model over the source record, with the no-show count rebuilt from the event history on
    the window the registry records for the model."""
    return score(coef, prior_asof, row["lead_time_days"], row["deprivation_decile"],
                 row["distance_km"], row["age_band"], row["appointment_type"])


def score_feature_store_current(coef, row):
    """The feature store as it now stands: the no-show count over the window currently configured (CR-2291
    widened it after deployment; the model was not re-fitted)."""
    return score(coef, row["prior_no_show_count"], row["lead_time_days"], row["deprivation_decile"],
                 row["distance_km"], row["age_band"], row["appointment_type"])
EOF

